3	import java.util.Map;
4	
5	import org.springframework.http.HttpStatus;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.web.bind.annotation.ResponseStatus;
8	
9	/**
10	 * Business rule: when an owner supplies a {@code postcode} it must be valid for the owner's city.
11	 * Validity is keyed by the city's region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD): NSW
12	 * 2000-2099, VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit
13	 * postcode. Postcode is optional: an owner created without one is accepted unchanged. Kept as a
14	 * small, self-contained unit so the rule can be enforced from the create flow without adding
15	 * complexity to the controller, mapper or service.
16	 */
17	public final class OwnerPostcodePolicy {
18	
19	    private static final Map<String, String> CITY_REGION = Map.of(
20	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
21	
22	    private static final Map<String, int[]> REGION_RANGE = Map.of(
23	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
24	
25	    private OwnerPostcodePolicy() {
26	    }
27	
28	    /**
29	     * Reject the owner when it supplies a postcode that is out of range for its city's region.
30	     * A missing postcode, or a city whose region is unknown, passes unchanged.
31	     *
32	     * @param owner the owner being created
33	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
34	     */
35	    public static void rejectInvalidPostcode(Owner owner) {
36	        String postcode = owner.getPostcode();
37	        if (postcode == null) {
38	            return;
39	        }
40	        String region = CITY_REGION.get(owner.getCity());
41	        if (region == null) {
42	            return;
43	        }
44	        int[] range = REGION_RANGE.get(region);
45	        int code = Integer.parseInt(postcode);
46	        if (code < range[0] || code > range[1]) {
47	            throw new InvalidPostcodeException();
48	        }
49	    }
50	
51	    /** Thrown when a supplied postcode is out of range for the city's region. */
52	    @ResponseStatus(HttpStatus.BAD_REQUEST)
53	    public static class InvalidPostcodeException extends RuntimeException {
54	    }
55	}
