2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.http.HttpStatus;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.web.bind.annotation.ResponseStatus;
10	
11	/**
12	 * Business rule: every owner is identified by a single derived {@code identityKey} of
13	 * {@code normalizedTelephone|email|householdId}. This consolidates the former separate
14	 * telephone, email and household duplicate checks into one key: on creation an owner is
15	 * rejected only when its WHOLE identityKey exactly matches an existing owner's. Because the
16	 * telephone is part of the key, two members of the same household (same householdId) with
17	 * different telephones have different identityKeys and are both allowed; only an exact
18	 * full-key match is a duplicate. Kept as a small, self-contained unit so the rule can be
19	 * enforced from the create flow without adding complexity to the controller or service.
20	 */
21	public final class OwnerIdentityPolicy {
22	
23	    private OwnerIdentityPolicy() {
24	    }
25	
26	    /**
27	     * Assign the owner's householdId (when it knowingly joins an existing household) and reject
28	     * the owner when its whole identityKey matches any other existing owner's.
29	     *
30	     * @param clinicService   source of the existing owners
31	     * @param owner           the owner being created
32	     * @param sharesHousehold whether the request opted in to a shared household
33	     * @throws DuplicateIdentityException if the identityKey is already in use
34	     */
35	    public static void rejectDuplicateIdentity(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
36	        assignHouseholdId(clinicService, owner, sharesHousehold);
37	        String key = identityKey(owner);
38	        for (Owner existing : clinicService.findAllOwners()) {
39	            if (!existing.getId().equals(owner.getId()) && key.equals(identityKey(existing))) {
40	                throw new DuplicateIdentityException();
41	            }
42	        }
43	    }
44	
45	    /** The owner's derived identity key: normalized telephone, email and household id, '|'-joined. */
46	    public static String identityKey(Owner owner) {
47	        return normalizeTelephone(owner.getTelephone()) + "|" + normalizeEmail(owner.getEmail()) + "|"
48	            + orEmpty(owner.getHouseholdId());
49	    }
50	
51	    /** Adopt the existing household's id when sharing was opted in and a matching owner already exists. */
52	    private static void assignHouseholdId(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
53	        if (!Boolean.TRUE.equals(sharesHousehold)) {
54	            return;
55	        }
56	        String lastName = normalizeHousehold(owner.getLastName());
57	        String address = normalizeHousehold(owner.getAddress());
58	        for (Owner existing : clinicService.findAllOwners()) {
59	            if (!existing.getId().equals(owner.getId())
60	                && lastName.equals(normalizeHousehold(existing.getLastName()))
61	                && address.equals(normalizeHousehold(existing.getAddress()))) {
62	                owner.setHouseholdId(householdId(lastName, address));
63	                return;
64	            }
65	        }
66	    }
67	
68	    private static String normalizeTelephone(String telephone) {
69	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
70	    }
71	
72	    private static String normalizeEmail(String email) {
73	        return email == null ? "" : email.toLowerCase();
74	    }
75	
76	    private static String normalizeHousehold(String value) {
77	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
78	    }
79	
80	    private static String orEmpty(String value) {
81	        return value == null ? "" : value;
82	    }
83	
84	    /** Derive a stable identifier shared by every owner in the same (last name, address) household. */
85	    private static String householdId(String lastName, String address) {
86	        try {
87	            byte[] digest = MessageDigest.getInstance("SHA-256")
88	                .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
89	            StringBuilder sb = new StringBuilder();
90	            for (int i = 0; i < 8; i++) {
91	                sb.append(String.format("%02x", digest[i]));
92	            }
93	            return sb.toString();
94	        }
95	        catch (NoSuchAlgorithmException e) {
96	            throw new IllegalStateException(e);
97	        }
98	    }
99	
100	    /** Thrown when another owner already has the same identityKey. */
101	    @ResponseStatus(HttpStatus.CONFLICT)
102	    public static class DuplicateIdentityException extends RuntimeException {
103	    }
104	}
