3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Business rule: on creation an owner is assigned a {@code customerCode} formatted
7	 * {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the upper-cased first three letters of the city,
8	 * LAST3 the upper-cased first three letters of the last name, and NNNN a per-city 4-digit
9	 * zero-padded sequence equal to one more than the number of owners already in that city
10	 * (e.g. {@code LON-SMI-0007}). Kept as a small, self-contained unit so the rule can be
11	 * applied from the create flow without adding complexity to the controller or service.
12	 */
13	public final class OwnerCustomerCodePolicy {
14	
15	    private OwnerCustomerCodePolicy() {
16	    }
17	
18	    /**
19	     * Assign the {@code customerCode} for a newly created owner.
20	     *
21	     * @param clinicService source of the current owner count
22	     * @param owner         the owner being created
23	     */
24	    public static void assignCustomerCode(ClinicService clinicService, Owner owner) {
25	        String city3 = prefix(owner.getCity());
26	        String last3 = prefix(owner.getLastName());
27	        int sequence = ownersInCity(clinicService, owner.getCity()) + 1;
28	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
29	    }
30	
31	    private static String prefix(String value) {
32	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
33	    }
34	
35	    private static int ownersInCity(ClinicService clinicService, String city) {
36	        return (int) clinicService.findAllOwners().stream()
37	            .filter(other -> city.equalsIgnoreCase(other.getCity()))
38	            .count();
39	    }
40	}
