5	/**
6	 * Converts a raw telephone into E.164 form. Kept as a small, self-contained unit so the
7	 * rule can be reused without adding complexity to the mapper or the owner model.
8	 */
9	final class E164Telephone {
10	
11	    private E164Telephone() {
12	    }
13	
14	    /**
15	     * Normalize {@code telephone} to E.164: keep an explicit leading '+' and its country
16	     * code when present, otherwise assume '+61' and drop a single leading '0' from the
17	     * national digits. Spaces, dashes and brackets are stripped. The result is returned
18	     * only when it holds 8 to 15 digits after the '+' and its national-number length is
19	     * valid for the country code (see
20	     * {@link org.springframework.samples.petclinic.service.OwnerTelephoneLengthPolicy}), so
21	     * an unconvertible number stays as its cleaned form and is rejected by validation.
22	     */
23	    static String toE164(String telephone) {
24	        if (telephone == null) {
25	            return null;
26	        }
27	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
28	        String digits;
29	        if (cleaned.startsWith("+")) {
30	            digits = cleaned.substring(1);
31	        }
32	        else {
33	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
34	            digits = "61" + national;
35	        }
36	        if (!digits.matches("[0-9]{8,15}")) {
37	            return cleaned;
38	        }
39	        OwnerTelephoneLengthPolicy.requireValidNationalLength(digits);
40	        return "+" + digits;
41	    }
42	}
