6	/**
7	 * Business rule: the national-number length of an owner's E.164 telephone must match its
8	 * country code ('+61' requires 9 national digits, '+1' requires 10). Kept as a small,
9	 * self-contained unit so the rule can be enforced during telephone normalization without
10	 * adding complexity to the mapper or the owner model.
11	 */
12	public final class OwnerTelephoneLengthPolicy {
13	
14	    private OwnerTelephoneLengthPolicy() {
15	    }
16	
17	    /**
18	     * Reject {@code digits} (country code plus national number, without the leading '+') when
19	     * its national length is wrong for the country code: '+61' requires 9 national digits and
20	     * '+1' requires 10. Any other country code is accepted.
21	     *
22	     * @param digits the E.164 digits without the leading '+'
23	     * @throws InvalidNationalNumberLengthException if the national length is wrong for the country
24	     */
25	    public static void requireValidNationalLength(String digits) {
26	        if (digits.startsWith("61") && digits.length() != 2 + 9) {
27	            throw new InvalidNationalNumberLengthException();
28	        }
29	        if (digits.startsWith("1") && digits.length() != 1 + 10) {
30	            throw new InvalidNationalNumberLengthException();
31	        }
32	    }
33	
34	    /** Thrown when an owner's national-number length does not match its E.164 country code. */
35	    @ResponseStatus(HttpStatus.BAD_REQUEST)
36	    public static class InvalidNationalNumberLengthException extends RuntimeException {
37	    }
38	}
